import pytest

from app import create_app


def client():
    return create_app().test_client()


def test_zero_qty_is_rejected():
    response = client().post("/total", json={"items": [{"price": 10.0, "qty": 0}]})
    assert response.status_code == 400


def test_negative_qty_is_rejected():
    response = client().post("/total", json={"items": [{"price": 10.0, "qty": -1}]})
    assert response.status_code == 400


def test_string_qty_is_rejected():
    response = client().post("/total", json={"items": [{"price": 10.0, "qty": "2"}]})
    assert response.status_code == 400


def test_float_qty_is_rejected():
    response = client().post("/total", json={"items": [{"price": 10.0, "qty": 2.5}]})
    assert response.status_code == 400


def test_boolean_qty_is_rejected():
    # bool is a subclass of int, so True/False must be rejected explicitly.
    response = client().post("/total", json={"items": [{"price": 10.0, "qty": True}]})
    assert response.status_code == 400


def test_valid_positive_integer_qty_is_accepted():
    response = client().post("/total", json={"items": [{"price": 10.0, "qty": 2}]})
    assert response.status_code == 200
    # (2 * 10.00) * 1.08 = 21.60
    assert response.get_json()["total"] == pytest.approx(21.60)


def test_coupon_still_applied_before_tax():
    response = client().post(
        "/total", json={"items": [{"price": 60.0, "qty": 1}], "coupon": "SAVE10"}
    )
    assert response.status_code == 200
    # (60.00 - 10.00) * 1.08 = 54.00
    assert response.get_json()["total"] == pytest.approx(54.00)
